function downloadTo(url: string, dest: string, redirects = 0): Promise<void> {
  return new Promise((resolve, reject) => {
    if (redirects > 5) {
      reject(new Error('too many redirects'))
      return
    }
    const req = get(url, (res: IncomingMessage) => {
      const status = res.statusCode ?? 0
      // GitHub release downloads 302-redirect to the asset CDN.
      if (status >= 300 && status < 400 && res.headers.location) {
        res.resume()
        downloadTo(res.headers.location, dest, redirects + 1).then(resolve, reject)
        return
      }
      if (status !== 200) {
        res.resume()
        reject(new Error(`HTTP ${status}`))
        return
      }
      const file = createWriteStream(dest)
      res.on('aborted', () => file.destroy(new Error('response aborted')))
      res.pipe(file)
      file.on('finish', () => file.close(() => resolve()))
      file.on('error', reject)
    })
    req.setTimeout(15_000, () => req.destroy(new Error('download timeout')))
    req.on('error', reject)
  })
}

